insert into cellar.products (type, status, source, specs, name, brand, brand_family, expression, producer, producer_id, proof, age_years, age_label, nas, expression_type, mash_style, mash_bill, spirit_type, bottled_in_bond, barrel_proof, finish, msrp_usd, is_core_range, catalog_included, aliases, image_url, source_url, source_checked_at, rarity)
select 'bourbon', 'confirmed', 'maker', case when r.img is null then '{}'::jsonb else jsonb_build_object('source_image_url', r.img) end, r.n, r.f, r.f, r.x, r.pr, r.mk::uuid, r.p, r.ay, r.al, r.nas, r.et::cellar.expression_type, r.ms::cellar.mash_style, r.mb, r.st::cellar.spirit_type, r.bib, r.bp, r.fin, r.msrp, r.core, true, coalesce(r.al2, '{}'::text[]), null, r.u, now(), r.rar::cellar.rarity
from jsonb_to_recordset($j$[{"n":"Milam & Greene Wildlife Collection: Live Oak","rar":"limited","f":"Milam & Greene","x":"Wildlife Collection: Live Oak","p":123.4,"ay":6.92,"al":"6.92 yr","nas":false,"et":"standard","ms":"high_rye","mb":"68% Corn, 20% Malted Rye, 12% Malted Barley","st":"bourbon","bib":false,"bp":true,"fin":null,"msrp":null,"core":false,"al2":["Milam & Greene Cask-Strength 2026 Wildlife Collection: Live Oak Straight Bourbon","Milam & Greene Live Oak"],"img":"https://cdn.shopify.com/s/files/1/0728/6449/7943/files/LIVEOAKPNG_copy.png?v=1779910052","u":"https://milamandgreenewhiskey.com/products/milam-and-greene-live-oak","pr":"Milam & Greene","mk":"a55f38fb-8063-4d53-9eb0-835b1a24fea9"},{"n":"Milam & Greene Wildlife Collection: Bluebonnet","rar":"limited","f":"Milam & Greene","x":"Wildlife Collection: Bluebonnet","p":113.5,"ay":5.58,"al":"5.58 yr","nas":false,"et":"standard","ms":"high_rye","mb":"70% Corn, 22% Malted Rye, 8% Malted Barley","st":"bourbon","bib":false,"bp":false,"fin":null,"msrp":null,"core":false,"al2":["Milam & Greene 2026 Wildlife Collection: Bluebonnet Straight Bourbon","Milam & Greene Bluebonnet"],"img":"https://cdn.shopify.com/s/files/1/0728/6449/7943/files/BLUEBONNET_SOLO_copy.png?v=1783477586","u":"https://milamandgreenewhiskey.com/products/milam-and-greene-wildlife-bluebonnet","pr":"Milam & Greene","mk":"a55f38fb-8063-4d53-9eb0-835b1a24fea9"},{"n":"Milam & Greene Triple Cask Cask Strength","rar":"limited","f":"Milam & Greene","x":"Triple Cask Cask Strength","p":117.2,"ay":null,"al":null,"nas":false,"et":"standard","ms":"high_rye","mb":"70% corn, 22% malted rye, 8% barley","st":"bourbon","bib":false,"bp":true,"fin":null,"msrp":null,"core":false,"al2":["Milam & Greene Triple Cask Cask Strength Straight Bourbon Whiskey"],"img":"https://cdn.shopify.com/s/files/1/0728/6449/7943/files/TRIPLECASK_CASK_STRENGHT_copy.png?v=1769566962","u":"https://milamandgreenewhiskey.com/products/triple-cask-cask-strength","pr":"Milam & Greene","mk":"a55f38fb-8063-4d53-9eb0-835b1a24fea9"}]$j$::jsonb) as r(n text, f text, x text, p numeric, ay numeric, al text, nas bool, et text, ms text, mb text, st text, bib bool, bp bool, fin text, msrp numeric, core bool, al2 text[], img text, u text, pr text, mk text, rar text)
where not exists (select 1 from cellar.products e where e.type = 'bourbon' and e.merged_into is null and coalesce(e.brand_family, '') = coalesce(r.f, '') and coalesce(e.expression, '') = coalesce(r.x, '') and coalesce(e.release_label, '') = '');
